# shellcheck shell=bash
# Monitor detection, layout selection and rendering.
[[ -n ${_DOTFILES_MONITORS:-} ]] && return 0
_DOTFILES_MONITORS=1

# Workspace slots per monitor when layout is auto-generated.
WS_PER_MONITOR=10

# Default app workspaces when no host preset exists.
APP_WS_VESKTOP_DEFAULT=6
APP_WS_OBSIDIAN_DEFAULT=5

# Single-monitor defaults: vesktop on ws 2, obsidian on ws 3.
APP_WS_VESKTOP_SINGLE=2
APP_WS_OBSIDIAN_SINGLE=3

# Chassis type codes from /sys/class/dmi/id/chassis_type (Linux kernel).
CHASSIS_LAPTOP=8
CHASSIS_NOTEBOOK=9
CHASSIS_DETACHABLE=10
CHASSIS_CONSOLE=14

detect_host_type() {
    if compgen -G "/sys/class/power_supply/BAT*" >/dev/null 2>&1; then
        printf 'laptop\n'
        return
    fi

    local chassis=""
    if [[ -r /sys/class/dmi/id/chassis_type ]]; then
        chassis="$(cat /sys/class/dmi/id/chassis_type)"
    fi
    case "$chassis" in
        "$CHASSIS_LAPTOP"|"$CHASSIS_NOTEBOOK"|"$CHASSIS_DETACHABLE"|"$CHASSIS_CONSOLE") printf 'laptop\n' ;;
        *)         printf 'desktop\n' ;;
    esac
}

detect_gpu_profile() {
    if command -v systemd-detect-virt >/dev/null 2>&1 && systemd-detect-virt -q; then
        printf 'vm\n'
        return
    fi

    local gpus=""
    if command -v lspci >/dev/null 2>&1; then
        gpus="$(lspci -nn 2>/dev/null | grep -Ei 'VGA compatible controller|3D controller|Display controller' || true)"
    fi

    local has_nvidia=0 has_amd=0 has_intel=0
    if grep -qi 'nvidia' <<<"$gpus"; then has_nvidia=1; fi
    if grep -qi 'amd/ati\|advanced micro devices' <<<"$gpus"; then has_amd=1; fi
    if grep -qi 'intel' <<<"$gpus"; then has_intel=1; fi

    if (( has_nvidia && (has_amd || has_intel) )); then
        printf 'hybrid\n'
    elif (( has_nvidia )); then
        printf 'nvidia\n'
    elif (( has_amd )); then
        printf 'amd\n'
    elif (( has_intel )); then
        printf 'intel\n'
    else
        printf 'software\n'
    fi
}

# Prints: NAME<TAB>MODE<TAB>POSITION<TAB>SCALE<TAB>WIDTH
detect_monitors() {
    if command -v hyprctl >/dev/null 2>&1 && [[ -n ${WAYLAND_DISPLAY:-} ]]; then
        hyprctl monitors -j 2>/dev/null | jq -r '.[] | [.name, ((.width|tostring) + "x" + (.height|tostring) + "@" + ((.refreshRate|floor)|tostring)), ((.x|tostring) + "x" + (.y|tostring)), (.scale|tostring), (.width|tostring)] | @tsv' && return 0
    fi

    local status name
    for status in /sys/class/drm/card*-*/status; do
        [[ -r $status ]] || continue
        [[ "$(cat "$status")" == "connected" ]] || continue
        name="$(basename "$(dirname "$status")")"
        name="${name#card*-}"
        [[ -n $name ]] || continue
        printf '%s\tpreferred\tauto\t1\t1920\n' "$name"
    done
}

join_quoted() {
    (($#)) || return 0
    local out="" value
    for value in "$@"; do
        out+="\"$value\" "
    done
    printf '%s' "${out% }"
}

repo_host_conf() {
    printf '%s/hosts/%s/monitors.conf.sh\n' "$DOTFILES_DIR" "$HOST_NAME"
}

write_repo_monitors() {
    local tmp target
    tmp="$(mktemp)"
    target="$(repo_host_conf)"

    {
        printf '# shellcheck shell=bash disable=SC2034\n'
        printf '# Monitor layout for host %s (generated by install.sh).\n' "$HOST_NAME"
        printf '# Edit this file or re-run: ./install.sh --monitors\n'
        printf '#\n'
        printf '# MON_NAME     output name (hyprctl monitors)\n'
        printf '# MON_MODE     resolution@refresh, or "preferred"\n'
        printf '# MON_POSITION global position, or "auto"\n'
        printf '# MON_SCALE    fractional scale, e.g. "1" or "1.25"\n'
        printf '# MON_WS_FIRST first workspace number on this monitor\n'
        printf '# MON_WS_COUNT how many workspace slots this monitor owns\n\n'
        printf 'MON_COUNT=%d\n' "$1"
        shift
        printf 'MON_NAME=(%s)\n' "$1"
        shift
        printf 'MON_MODE=(%s)\n' "$1"
        shift
        printf 'MON_POSITION=(%s)\n' "$1"
        shift
        printf 'MON_SCALE=(%s)\n' "$1"
        shift
        printf 'MON_WS_FIRST=(%s)\n' "$1"
        shift
        printf 'MON_WS_COUNT=(%s)\n' "$1"
        shift
        printf '\n# Workspaces for apps that should always open on a fixed workspace.\n'
        printf 'APP_WS_VESKTOP=%s\n' "$1"
        shift
        printf 'APP_WS_OBSIDIAN=%s\n' "$1"
    } >"$tmp"

    if [[ -f $target ]] && cmp -s -- "$tmp" "$target"; then
        ok "monitor layout unchanged: hosts/$HOST_NAME/monitors.conf.sh"
        rm -f -- "$tmp"
        return 0
    fi

    if [[ -f $target ]]; then
        log "Proposed changes to hosts/$HOST_NAME/monitors.conf.sh:"
        diff -u -- "$target" "$tmp" || true
        if ! tui_confirm "Write this monitor layout?" yes; then
            warn "monitor layout not written"
            rm -f -- "$tmp"
            return 1
        fi
        backup_path "$target"
    fi

    if (( DRY_RUN )); then
        log "${C_DIM}[dry-run]${C_RESET} write $target"
    else
        install -m 0644 -- "$tmp" "$target"
        ok "wrote hosts/$HOST_NAME/monitors.conf.sh"
    fi
    rm -f -- "$tmp"
}

# Render ~/.config/hypr/monitors.lua and ~/.config/hypr/monitors.conf.sh
# from the host layout file.
render_monitors() {
    local conf lua_tmp conf_tmp
    conf="$(repo_host_conf)"

    MON_COUNT=0
    MON_NAME=() MON_MODE=() MON_POSITION=() MON_SCALE=()
    MON_WS_FIRST=() MON_WS_COUNT=()
    APP_WS_VESKTOP=0
    APP_WS_OBSIDIAN=0

    if [[ ! -r $conf ]]; then
        warn "no monitor layout for host $HOST_NAME; using auto"
        MON_COUNT=0
        APP_WS_VESKTOP=0
        APP_WS_OBSIDIAN=0
    else
        # shellcheck source=/dev/null
        if ! source "$conf"; then
            warn "invalid monitor layout in $conf; using auto"
            MON_COUNT=0
            APP_WS_VESKTOP=0
            APP_WS_OBSIDIAN=0
        fi
    fi

    local generated=0
    if ((MON_COUNT == 0)); then
        local -a detected=()
        local idx dname dmode dpos dscale _width first=1
        mapfile -t detected < <(detect_monitors)
        for idx in "${!detected[@]}"; do
            IFS=$'\t' read -r dname dmode dpos dscale _width <<<"${detected[$idx]}"
            [[ -n $dname ]] || continue
            MON_NAME+=("$dname")
            MON_MODE+=("${dmode:-preferred}")
            MON_POSITION+=("${dpos:-auto}")
            MON_SCALE+=("${dscale:-1}")
            MON_WS_FIRST+=("$first")
            MON_WS_COUNT+=("$WS_PER_MONITOR")
            first=$((first + WS_PER_MONITOR))
        done
        MON_COUNT=${#MON_NAME[@]}
        if ((MON_COUNT > 0)); then
            generated=1
            ((APP_WS_VESKTOP)) || APP_WS_VESKTOP=$APP_WS_VESKTOP_DEFAULT
            ((APP_WS_OBSIDIAN)) || APP_WS_OBSIDIAN=$APP_WS_OBSIDIAN_DEFAULT
            info "no monitor preset: generated $WS_PER_MONITOR workspace slots per detected monitor"
        fi
    fi

    lua_tmp="$(mktemp)"
    conf_tmp="$(mktemp)"

    {
        printf -- '-- Generated by install.sh from hosts/%s/monitors.conf.sh.\n' "$HOST_NAME"
        printf -- '-- Do not edit by hand.\n\n'
        printf 'local M = {}\n\n'
        local i
        for ((i = 0; i < MON_COUNT; i++)); do
            printf 'M[#M + 1] = { name = "%s", mode = "%s", position = "%s", scale = "%s", ws_first = %s, ws_count = %s }\n' \
                "${MON_NAME[$i]}" "${MON_MODE[$i]}" "${MON_POSITION[$i]}" "${MON_SCALE[$i]}" "${MON_WS_FIRST[$i]}" "${MON_WS_COUNT[$i]}"
        done
        printf '\nM.app_workspaces = { vesktop = %s, obsidian = %s }\n\n' "${APP_WS_VESKTOP:-0}" "${APP_WS_OBSIDIAN:-0}"
        printf 'for _, m in ipairs(M) do\n'
        printf '    hl.monitor({ output = m.name, mode = m.mode, position = m.position, scale = m.scale })\n'
        printf 'end\n\n'
        printf 'for _, m in ipairs(M) do\n'
        printf '    for i = 0, m.ws_count - 1 do\n'
        printf '        hl.workspace_rule({ workspace = tostring(m.ws_first + i), monitor = m.name, persistent = true })\n'
        printf '    end\n'
        printf 'end\n\n'
        printf 'return M\n'
    } >"$lua_tmp"

    if ((generated)); then
        {
            printf '# Installed copy. Generated from detected monitors (no host preset).\n'
            printf 'MON_COUNT=%d\n' "$MON_COUNT"
            printf 'MON_NAME=(%s)\n' "$(join_quoted "${MON_NAME[@]}")"
            printf 'MON_MODE=(%s)\n' "$(join_quoted "${MON_MODE[@]}")"
            printf 'MON_POSITION=(%s)\n' "$(join_quoted "${MON_POSITION[@]}")"
            printf 'MON_SCALE=(%s)\n' "$(join_quoted "${MON_SCALE[@]}")"
            printf 'MON_WS_FIRST=(%s)\n' "${MON_WS_FIRST[*]}"
            printf 'MON_WS_COUNT=(%s)\n' "${MON_WS_COUNT[*]}"
            printf 'APP_WS_VESKTOP=%s\n' "$APP_WS_VESKTOP"
            printf 'APP_WS_OBSIDIAN=%s\n' "$APP_WS_OBSIDIAN"
        } >"$conf_tmp"
    elif [[ -r $conf ]]; then
        {
            printf '# Installed copy. Source of truth: hosts/%s/monitors.conf.sh\n' "$HOST_NAME"
            cat -- "$conf"
        } >"$conf_tmp"
    else
        {
            printf 'MON_COUNT=0\n'
            printf 'MON_NAME=()\nMON_MODE=()\nMON_POSITION=()\nMON_SCALE=()\nMON_WS_FIRST=()\nMON_WS_COUNT=()\n'
        } >"$conf_tmp"
    fi

    copy_file "$lua_tmp" "$REAL_HOME/.config/hypr/monitors.lua" 0644 \
        "$DOTFILES_DIR/hosts/$HOST_NAME/monitors.conf.sh"
    copy_file "$conf_tmp" "$REAL_HOME/.config/hypr/monitors.conf.sh" 0644 \
        "$DOTFILES_DIR/hosts/$HOST_NAME/monitors.conf.sh"
    rm -f -- "$lua_tmp" "$conf_tmp"

    if declare -F install_dock_conf >/dev/null 2>&1; then
        install_dock_conf
    fi
}

commit_layout() {
    local -a n=() m=() p=() s=() f=() c=()
    local i
    for ((i = 0; i < ${MON_COUNT:-0}; i++)); do
        n+=("${MON_NAME[$i]}")
        m+=("${MON_MODE[$i]}")
        p+=("${MON_POSITION[$i]}")
        s+=("${MON_SCALE[$i]}")
        f+=("${MON_WS_FIRST[$i]}")
        c+=("${MON_WS_COUNT[$i]}")
    done
    write_repo_monitors "${MON_COUNT:-0}" \
        "$(join_quoted "${n[@]}")" "$(join_quoted "${m[@]}")" \
        "$(join_quoted "${p[@]}")" "$(join_quoted "${s[@]}")" \
        "${f[*]}" "${c[*]}" \
        "${APP_WS_VESKTOP:-0}" "${APP_WS_OBSIDIAN:-0}"
}

configure_monitors() {
    local rows
    mapfile -t rows < <(detect_monitors)
    if ((${#rows[@]} == 0)); then
        warn "no connected monitors detected; using Hyprland auto layout"
        write_repo_monitors 0 "" "" "" "" "" "" 0 0 || true
        render_monitors
        return 0
    fi

    local names=()
    local name
    for name in "${rows[@]}"; do
        IFS=$'\t' read -r name _ _ _ _ <<<"$name"
        names+=("$name")
    done

    if (( ASSUME_YES )); then
        info "detected monitors: ${names[*]}"
        local order=()
        local remaining=("${names[@]}")
        while ((${#remaining[@]})); do
            order+=("${remaining[0]}")
            remaining=("${remaining[@]:1}")
        done
        build_layout "${order[*]}" ""
        return
    fi

    local choice
    choice="$(tui_radio "Monitor layout (${#names[@]} detected)" \
        "Single monitor" \
        "Two or more (choose order and positions)" \
        "Auto (preferred mode, automatic positions)" \
        "Preset dill-desktop (example two-monitor preset)" \
        "Edit hosts/$HOST_NAME/monitors.conf.sh manually")" || return 1

    case "$choice" in
        Single*)
            local picked
            if ((${#names[@]} == 1)); then
                picked="${names[0]}"
            else
                picked="$(tui_radio "Primary monitor" "${names[@]}")" || return 1
            fi
            build_layout "$picked" single
            ;;
        Two*)
            local remaining=("${names[@]}") order=() picked i
            while ((${#remaining[@]})); do
                picked="$(tui_radio "Position $(( ${#order[@]} + 1 )) (left to right)" "${remaining[@]}")" || return 1
                order+=("$picked")
                local next=()
                for i in "${remaining[@]}"; do
                    [[ $i == "$picked" ]] || next+=("$i")
                done
                remaining=("${next[@]}")
            done
            build_layout "${order[*]}" multi
            ;;
        Auto*)
            build_layout "${names[*]}" auto
            ;;
        Preset*)
            local preset="$DOTFILES_DIR/hosts/desktop/monitors.conf.sh"
            if [[ ! -r $preset ]]; then
                err "preset not found: $preset"
                return 1
            fi
            # shellcheck source=/dev/null
            source "$preset"
            commit_layout || return 1
            render_monitors
            ok "applied preset dill-desktop"
            ;;
        Edit*)
            "${EDITOR:-micro}" "$(repo_host_conf)"
            render_monitors
            ;;
        *)
            return 1
            ;;
    esac
}

build_layout() {
    local order_str="$1" kind="$2"
    local order=() i
    read -r -a order <<<"$order_str"

    local out_names=() out_modes=() out_pos=() out_scales=() out_first=() out_counts=()
    local mode scale w x=0 ws_count name

    ws_count="$(tui_input "Workspaces per monitor" "$WS_PER_MONITOR")"
    [[ $ws_count =~ ^[1-9][0-9]*$ ]] || ws_count=$WS_PER_MONITOR

    for i in "${!order[@]}"; do
        local mon="${order[$i]}"
        local detected_mode="" detected_scale="1" detected_width="1920"
        local row
        for row in "${rows[@]}"; do
            IFS=$'\t' read -r name detected_mode _ detected_scale detected_width <<<"$row"
            [[ $name == "$mon" ]] && break
        done

        if [[ $kind == auto ]]; then
            mode="preferred"
            scale="${detected_scale:-1}"
            out_pos+=("auto")
        else
            mode="$(tui_input "Mode for $mon (preferred or WxH@Hz)" "${detected_mode:-preferred}")"
            scale="$(tui_input "Scale for $mon" "${detected_scale:-1}")"
            if [[ $kind == single ]]; then
                out_pos+=("0x0")
            else
                out_pos+=("${x}x0")
            fi
        fi

        out_names+=("$mon")
        out_modes+=("$mode")
        out_scales+=("$scale")
        out_first+=("$((i * ws_count + 1))")
        out_counts+=("$ws_count")

        w="${detected_width:-1920}"
        x="$(awk -v x="$x" -v w="$w" -v s="$scale" 'BEGIN { printf "%d", x + (s > 0 ? w / s : w) }')"
    done

    local vesktop=$APP_WS_VESKTOP_SINGLE obsidian=$APP_WS_OBSIDIAN_SINGLE
    if ((${#out_first[@]} > 1)); then
        vesktop=$(( out_first[1] + 1 ))
        obsidian=$(( out_first[1] + 2 ))
    fi

    write_repo_monitors "${#out_names[@]}" \
        "$(join_quoted "${out_names[@]}")" \
        "$(join_quoted "${out_modes[@]}")" \
        "$(join_quoted "${out_pos[@]}")" \
        "$(join_quoted "${out_scales[@]}")" \
        "${out_first[*]}" \
        "${out_counts[*]}" \
        "$vesktop" "$obsidian" || return 1

    render_monitors
}
